private void init() {
    Device device = new Device(this);
    this.device = device;
    device.setFullScreen();
    this.myWebView = (WebView) findViewById(com.dreamtv.app.R.id.webview);
    this.exoPlayerView = (PlayerView) findViewById(com.dreamtv.app.R.id.idExoPlayerVIew);
    this.vlcVideoLayout = (VLCVideoLayout) findViewById(com.dreamtv.app.R.id.vlc_player_view);
    this.vlc_parent = (FrameLayout) findViewById(com.dreamtv.app.R.id.vlc_parent);
    this.player = new Player(this, this.exoPlayerView, this.vlcVideoLayout, this.vlc_parent);
    WebEngine webEngine = new WebEngine(this.myWebView, this, this.device, this.player);
    this.webEngine = webEngine;
    webEngine.initApp(this.defaultHost);
    NetworkTimer networkTimer = new NetworkTimer(this, this.webEngine);
    this.timer = networkTimer;
    networkTimer.startNetworkCheckTimer();
}
